import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

const validatorOptions = {strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0];
const schemaValidator = new Ajv(validatorOptions);

function validationSchema(schema: object): object {
  const source = schema as Record<string, unknown>;
  const projected: Record<string, unknown> = {};
  for (const keyword of ['type', 'enum', 'required'] as const) {
    if (keyword in source) projected[keyword] = source[keyword];
  }
  if (source.properties && typeof source.properties === 'object') {
    projected.properties = Object.fromEntries(
      Object.entries(source.properties).map(([name, child]) => [
        name,
        child && typeof child === 'object' ? validationSchema(child) : child,
      ])
    );
  }
  if (source.items && typeof source.items === 'object') projected.items = validationSchema(source.items);
  return projected;
}

function schemaRejection(errors: unknown[]): ToolResponse {
  const error = errors[0];
  const keyword = errorProperty(error, 'keyword');
  const params = errorProperty(error, 'params');
  const missingProperty = errorProperty(params, 'missingProperty');
  const expectedType = errorProperty(params, 'type');
  const instancePath = errorProperty(error, 'instancePath');
  const propertyPath =
    typeof missingProperty === 'string'
      ? `${typeof instancePath === 'string' ? instancePath : ''}/${missingProperty.replace(/~/g, '~0').replace(/\//g, '~1')}`
      : (typeof instancePath === 'string' && instancePath) || 'input';
  const issue =
    keyword === 'required'
      ? 'is required'
      : keyword === 'type' && typeof expectedType === 'string'
        ? `must be a ${expectedType}`
        : `must satisfy ${String(keyword)}`;
  return {result: `Invalid input at ${propertyPath}: ${issue}.`};
}

function errorProperty(error: unknown, property: string): unknown {
  if (typeof error !== 'object' || error === null || !(property in error)) return undefined;
  return (error as Record<string, unknown>)[property];
}

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const staticValidator =
      typeof definition === 'function' ? undefined : this.compileSchema(resolved.inputSchema, resolved.name);
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  private compileSchema(schema: object, name: string): ValidateFunction {
    try {
      return schemaValidator.compile(validationSchema(schema));
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${name}: ${message}`, {cause: error});
    }
  }

  private dynamicValidator(schema: object, name: string): ValidateFunction {
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const validator = this.compileSchema(schema, name);
    this.dynamicValidators.set(schema, validator);
    return validator;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns schema rejections as tool results; only an unknown tool name throws (see specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = tool.staticValidator ?? this.dynamicValidator(definition.inputSchema, definition.name);
    if (!validate(input)) {
      const rejection = schemaRejection(validate.errors ?? []);
      log.warn('tool', 'input rejected', {name, result: rejection.result});
      return rejection;
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import Ajv from 'ajv';
import {jest} from '@jest/globals';
import type {ToolDefinition} from '../../types/ai.js';
import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  afterEach(() => setLogger(undefined));

  const registerStringLookup = (registry: ToolRegistry): void => {
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
          required: ['identifier'],
        },
      },
      async () => 'found'
    );
  };

  it('returns a required-property rejection without running the tool', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    const weatherDefinition = {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    } satisfies ToolDefinition;
    registry.register(weatherDefinition, async () => ((executorCalls += 1), 'sunny'));

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, rejectionNamesRequiredLocation: /location.*required/i.test(response.result)}).toEqual({
      executorCalls: 0,
      rejectionNamesRequiredLocation: true,
    });
  });

  it('names the full path of a missing nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_lookup',
        description: 'Look up a nested value',
        inputSchema: {
          type: 'object',
          properties: {
            user: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
          required: ['user'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('nested_lookup', {user: {}});

    expect(response.result).toContain('/user/location');
  });

  it('names the full path of a nested property with the wrong type', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_lookup',
        description: 'Look up a nested value',
        inputSchema: {
          type: 'object',
          properties: {user: {type: 'object', properties: {location: {type: 'string'}}}},
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('nested_lookup', {user: {location: 123}});

    expect(response.result).toContain('/user/location');
  });

  it('describes the expected type for an invalid field without echoing its value', async () => {
    const registry = new ToolRegistry();
    registerStringLookup(registry);

    const response = await registry.execute('lookup_record', {identifier: 912345});

    expect({
      namesExpectedType: response.result.includes('string'),
      leaksValue: response.result.includes('912345'),
    }).toEqual({
      namesExpectedType: true,
      leaksValue: false,
    });
  });

  it('does not enforce schema constraints beyond required, type, and enum', async () => {
    const registry = new ToolRegistry();
    let received: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'short_label',
        description: 'Accept a short label',
        inputSchema: {
          type: 'object',
          properties: {label: {type: 'string', minLength: 4}},
          required: ['label'],
        },
      },
      async input => {
        received = input;
        return 'accepted';
      }
    );

    const input = {label: 'x', extra: true};
    const response = await registry.execute('short_label', input);

    expect({response, received}).toEqual({response: {result: 'accepted'}, received: input});
  });

  it('compiles a static schema only once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'cached_tool',
        description: 'A tool with a cached schema',
        inputSchema: {type: 'object', properties: {value: {type: 'string'}}},
      },
      async () => 'ok'
    );

    for (let attempt = 0; attempt < 10; attempt += 1) {
      await registry.execute('cached_tool', {value: 'valid'});
    }

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  it('names the field path for a wrong-typed property', async () => {
    const registry = new ToolRegistry();
    registerStringLookup(registry);

    const response = await registry.execute('lookup_record', {identifier: 123456789});

    expect(response.result).toContain('/identifier');
  });

  it('names the property in a top-level type rejection', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up a record by identifier',
        inputSchema: {type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']},
      },
      async () => 'found'
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect(response.result).toContain('/ssn');
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required, including its full nested path, and never invokes the executor ([validated by: returns a required-property rejection without running the tool](../../src/orchestration/tools/registry.test.ts#L25), [validated by: names the full path of a missing nested required property](../../src/orchestration/tools/registry.test.ts#L43), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: names the field path for a wrong-typed property](../../src/orchestration/tools/registry.test.ts#L148), [validated by: names the property in a top-level type rejection](../../src/orchestration/tools/registry.test.ts#L157), [validated by: describes the expected type for an invalid field without echoing its value](../../src/orchestration/tools/registry.test.ts#L88), [validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- A wrong-typed property nested inside an object is reported using its complete JSON Pointer path ([validated by: names the full path of a nested property with the wrong type](../../src/orchestration/tools/registry.test.ts#L69)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- Other JSON Schema constraints such as `minLength` are not enforced by registry validation ([validated by: does not enforce schema constraints beyond required, type, and enum](../../src/orchestration/tools/registry.test.ts#L103)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static schema only once across repeated executions](../../src/orchestration/tools/registry.test.ts#L128)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
